	'messages:apihelp-query-param-prop' => 'en:Which properties to get for the queried pages.',
	'messages:apihelp-query-param-indexpageids' => 'en:Include an additional pageids section listing all returned page IDs.',
	'messages:apihelp-query-param-export' => 'en:Export the current revisions of all given or generated pages.',
